/**
 * What does the shipped pipeline actually do on a cold day?
 * Runs the real weatherRules, laterAdvice and ranking for three day shapes.
 */
import { readFileSync } from "node:fs";
import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
import { personalBand, weatherRules, planningTemp } from "@/lib/generator/rules";
import { rankTopN } from "@/lib/generator/rank";
import { diversify } from "@/lib/generator/diversity";
import { laterAdvice } from "@/lib/weather/advice";

const DIR = "/private/tmp/claude-501/-Users-1curafu-Desktop-Fitcheck-Fitcheck/903d62f8-76c6-4d8e-aaef-442496fb144e/scratchpad";
const rows = JSON.parse(readFileSync(`${DIR}/closet.json`, "utf8")) as (CandidateItem & {
  name: string;
})[];
const items: CandidateItem[] = rows.map((r) => ({
  id: r.id,
  category: r.category,
  colors: r.colors ?? [],
  formality: r.formality,
  seasons: r.seasons ?? [],
  material: r.material,
  texture: r.texture,
  pattern: r.pattern,
