import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { StatsView } from "../stats-view";

const base = {
  value: "€1,240.00",
  totalWears: 47,
  avgCostPerWear: "€26.38",
  mostWorn: [
    { id: "i1", name: "Brushed Oxford", sub: "Worn 12 times" },
