import { readFileSync } from "node:fs";
import { biggestGap, GAP_CANDIDATES, NEUTRAL_WEATHER } from "@/lib/stats/gap";
import { eligibleByCategory, REQUIRED_CATEGORIES, type CandidateItem } from "@/lib/generator/candidates";
import { personalBand } from "@/lib/generator/rules";
import type { UiOccasion } from "@/lib/generator/types";

const DIR = "/private/tmp/claude-501/-Users-1curafu-Desktop-Fitcheck-Fitcheck/903d62f8-76c6-4d8e-aaef-442496fb144e/scratchpad";
const rows = JSON.parse(readFileSync(`${DIR}/closet.json`, "utf8")) as (CandidateItem & { name: string })[];
const closet: CandidateItem[] = rows.map((r) => ({
  id: r.id, category: r.category, colors: r.colors ?? [], formality: r.formality,
  seasons: r.seasons ?? [], material: r.material, texture: r.texture, pattern: r.pattern,
}));

const ALL: UiOccasion[] = ["everyday", "work", "weekend", "evening"];

function count(c: CandidateItem[], occasions: UiOccasion[]) {
  return occasions.reduce((total, o) => {
    const by = eligibleByCategory(c, {
      band: personalBand(o, null), weather: NEUTRAL_WEATHER, season: undefined,
      excludeItemIds: [], maxAccessories: 0,
    });
    const slots = REQUIRED_CATEGORIES.map((k) => (by[k] ?? []).length);
    return total + (slots.some((n) => n === 0) ? 0 : slots.reduce((a, b) => a * b, 1));
  }, 0);
}

const before = count(closet, ALL);
const gap = biggestGap(closet, ALL)!;
console.log(`closet: ${closet.length} pieces`);
console.log(`buildable now (4 occasions, slot product): ${before}`);
console.log(`biggest gap: ${gap.candidate.label} → +${gap.unlocks}  (${Math.round((gap.unlocks / before) * 100)}% more)`);
console.log(`same, ONE occasion (everyday): now ${count(closet, ["everyday"])}, +${biggestGap(closet, ["everyday"])!.unlocks}`);
console.log("\nall candidates, 4 occasions:");
for (const c of GAP_CANDIDATES) {
  const one = biggestGap(closet.filter(() => true), ALL);
  void one;
}
for (const c of GAP_CANDIDATES) {
  const hypo: CandidateItem = {
    id: "__h__", category: c.category, colors: c.colors, formality: c.formality,
    seasons: [], material: null, pattern: "solid", texture: null,
  };
  const after = count([...closet, hypo], ALL);
  console.log(`  ${c.label.padEnd(24)} +${after - before}`);
}

